\subsection{Follow-up Work}
\label{sec:followup_en_tr}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We dissect the output layer of CGRU NMT \cite{nematus}
which is conditioned (Equation~\ref{eq:cond1}) on the hidden state $h_t$ of the decoder,
the feedback embedding $y_{t-1}$ and the weighted context vector $c_t$. We experiment with
a \tit{simple output} (Equation~\ref{eq:cond2}) which depends only on $h_t$ similar to \newcite{Sutskever2014}.
The target probability distribution is computed (Equation~\ref{eq:softmax}) using softmax on top of this output transformed with $W_o$.

\begin{align}
\label{eq:cond1}
o_t &= \tanh (\mathbf{W_h}h_t + y_{t-1} + \mathbf{W_c}c_t)\\
\label{eq:cond2}
o_t &= \tanh(\mathbf{W_h}h_t) \\
P(y_t) &= \text{softmax}(\mathbf{W_o} o_t) \label{eq:softmax}
\end{align}

\begin{align}
\label{eq:cond1}
o_t &= \tanh (\mathbf{W_h}h_t + y_{t-1} + \mathbf{W_c}c_t)\\
\label{eq:cond2}
o_t &= \tanh(\mathbf{W_h}h_t) \\
P(y_t) &= \text{softmax}(\mathbf{W_o} o_t) \label{eq:softmax}
\end{align}

